/**
 * The Asulins ident, synthesised rather than prompted.
 *
 *   pnpm --filter @amanda/art exec tsx src/studioSting.ts
 *   → assets/raw/studio/sting/*.mp3
 *
 * ═══ WHY THIS IS NOT ASKED FOR ═══
 *
 * The first four were generated by the same model that makes the game's
 * sound effects, and Or: *"the sounds are no good and not pleasant to the
 * ear. Think about the opening sound of Supercell. Of Netflix. Of EA Sports.
 * The connect sound of ICQ."*
 *
 * He is right, and the fault is the method rather than the wording. That
 * model is an EFFECTS model — footsteps, doors, explosions — and the things
 * he just named are not effects. They are music: exact pitches, an exact
 * interval, one chosen timbre, nothing else. Asked for "two warm synthesizer
 * notes", a texture model returns a texture, and twice now it has.
 *
 * So these are computed. Every number below is a decision I can defend and
 * change — a pitch, an interval, a decay — instead of a sentence I hope
 * lands. It also costs nothing to try the next one.
 *
 * ═══ WHAT THE ONES HE NAMED HAVE IN COMMON ═══
 *
 * Netflix is two notes. ICQ is two notes. Supercell is a short rise ending
 * on one. None of them is a tune — a tune has a second half you begin
 * waiting for, and this plays before every single launch.
 *
 * What makes them stick is the TIMBRE and the INTERVAL, which is why there
 * is an FM bell and a filtered thud in here rather than a sine wave.
 *
 * And one of them is the brief: a LOW note and a HIGH note, the big one and
 * the small one. That is the logo, in sound.
 */
import { mkdirSync, writeFileSync, existsSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { join } from "node:path";
import { REPO_ROOT } from "./catalog.js";

const OUT = join(REPO_ROOT, "assets", "raw", "studio", "sting");
const RATE = 44100;

/* ── the instrument ────────────────────────────────────────────────── */

type Buf = Float64Array;

const seconds = (n: number) => Math.round(n * RATE);
const make = (dur: number): Buf => new Float64Array(seconds(dur));

/** Equal temperament from A4 = 440, so intervals are exact rather than eyeballed. */
function note(name: string): number {
  const STEPS: Record<string, number> = {
    C: -9, "C#": -8, D: -7, "D#": -6, E: -5, F: -4,
    "F#": -3, G: -2, "G#": -1, A: 0, "A#": 1, B: 2,
  };
  const m = /^([A-G]#?)(-?\d)$/.exec(name);
  if (!m) throw new Error(`not a note: ${name}`);
  const semis = STEPS[m[1]!]! + (Number(m[2]) - 4) * 12;
  return 440 * Math.pow(2, semis / 12);
}

/**
 * An exponential decay with a short attack.
 *
 * The attack is 4ms rather than zero on purpose: a waveform that starts at
 * full amplitude starts with a CLICK, and a click is the difference between
 * a bell and a bug.
 */
function env(i: number, n: number, attack = 0.004, decay = 3.5): number {
  const t = i / RATE;
  const a = Math.min(1, t / attack);
  return a * Math.exp((-decay * i) / n);
}

/**
 * One FM bell.
 *
 * Two oscillators: a carrier at the pitch, and a modulator at `ratio` times
 * it bending the carrier's phase. The modulator's own envelope decays faster
 * than the note, which is what a real struck bell does — bright at the strike
 * and pure as it rings out. A sine alone sounds like a test tone.
 */
function bell(
  freq: number,
  dur: number,
  { ratio = 2.0, index = 3.2, decay = 3.6, gain = 1 } = {},
): Buf {
  const n = seconds(dur);
  const out = make(dur);
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    const mi = index * Math.exp((-decay * 2.2 * i) / n);
    const mod = Math.sin(2 * Math.PI * freq * ratio * t) * mi;
    out[i] = Math.sin(2 * Math.PI * freq * t + mod) * env(i, n, 0.004, decay) * gain;
  }
  return out;
}

/** A low body note: a few harmonics, no brightness. The thud under a hit. */
function thud(freq: number, dur: number, { decay = 4.2, gain = 1 } = {}): Buf {
  const n = seconds(dur);
  const out = make(dur);
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    // A touch of downward pitch bend — every drum does it, and it is most of
    // why a flat sine sounds synthetic and a bent one sounds hit.
    const f = freq * (1 + 0.28 * Math.exp((-14 * i) / n));
    const s =
      Math.sin(2 * Math.PI * f * t) +
      0.34 * Math.sin(4 * Math.PI * f * t) +
      0.12 * Math.sin(6 * Math.PI * f * t);
    out[i] = (s / 1.46) * env(i, n, 0.002, decay) * gain;
  }
  return out;
}

/** Filtered noise, for a whoosh or the air around a hit. */
function air(dur: number, { cutoff = 2600, decay = 3, gain = 1, rise = false } = {}): Buf {
  const n = seconds(dur);
  const out = make(dur);
  let lp = 0;
  let seed = 12345;
  for (let i = 0; i < n; i++) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const white = (seed / 0x3fffffff) - 1;
    const k = Math.min(1, (2 * Math.PI * cutoff) / RATE);
    lp += k * (white - lp);
    const shape = rise ? Math.pow(i / n, 2.2) : env(i, n, 0.002, decay);
    out[i] = lp * shape * gain;
  }
  return out;
}

/** Lay one sound into another at a time offset. */
function at(into: Buf, src: Buf, start: number): void {
  const o = seconds(start);
  for (let i = 0; i < src.length && o + i < into.length; i++) into[o + i]! += src[i]!;
}

/**
 * A small room.
 *
 * ═══ PARALLEL AND DAMPED, WHICH THE FIRST VERSION WAS NEITHER ═══
 *
 * It was four feedback combs applied to the same buffer IN PLACE, one after
 * another, with no damping. Two things wrong with that, and the spectrogram
 * showed both: applied in series each comb feeds the next, so they compound
 * into a resonator rather than a room; and with no damping the high partials
 * ring as long as the low ones, which nothing real does. The decay came out
 * striped with fixed resonances — the sound of a metal pipe, which is a fair
 * description of "not pleasant to the ear".
 *
 * Schroeder's arrangement instead: the combs run in PARALLEL from the dry
 * signal and are summed, then two allpasses in series smear what is left.
 * The delays are mutually prime in samples so their resonances do not line
 * up and reinforce each other, and each comb's feedback path is lowpassed,
 * so the room swallows the bright partials first — which is what air does.
 */
function room(src: Buf, { mix = 0.22, size = 1, damp = 0.32 } = {}): Buf {
  const n = src.length;
  const wet = new Float64Array(n);

  // Mutually prime lengths. Shared factors put two combs' resonances on top
  // of each other, which is the ringing this is here to avoid.
  const combs = [1327, 1733, 2113, 2591, 2927].map((d) => Math.max(1, Math.round(d * size)));
  for (const d of combs) {
    const buf = new Float64Array(d);
    let lp = 0;
    let i = 0;
    for (let j = 0; j < n; j++) {
      const out = buf[i]!;
      wet[j]! += out;
      // One-pole lowpass inside the feedback loop: each pass round the room
      // loses its top end, so a cymbal dies before a drum does.
      lp = out * (1 - damp) + lp * damp;
      buf[i] = src[j]! + lp * 0.76;
      i = (i + 1) % d;
    }
  }
  for (let j = 0; j < n; j++) wet[j]! /= combs.length;

  // Two allpasses: they change phase, not amplitude, which turns the combs'
  // discrete echoes into something closer to a wash.
  for (const d of [389, 127]) {
    const buf = new Float64Array(d);
    let i = 0;
    for (let j = 0; j < n; j++) {
      const bufOut = buf[i]!;
      const input = wet[j]!;
      wet[j] = -input + bufOut;
      buf[i] = input + bufOut * 0.5;
      i = (i + 1) % d;
    }
  }

  const out = new Float64Array(n);
  for (let j = 0; j < n; j++) out[j] = src[j]! * (1 - mix) + wet[j]! * mix;
  return out;
}

/** Peak-normalise, then a gentle soft clip so nothing ever crackles. */
function finish(buf: Buf, peak = 0.89): Buf {
  let max = 0;
  for (const v of buf) max = Math.max(max, Math.abs(v));
  const k = max > 0 ? peak / max : 1;
  const out = make(buf.length / RATE);
  for (let i = 0; i < buf.length; i++) out[i] = Math.tanh(buf[i]! * k * 1.1) * 0.95;
  // 6ms fade at each end, so the file itself can never click.
  const f = seconds(0.006);
  for (let i = 0; i < f; i++) {
    out[i]! *= i / f;
    out[out.length - 1 - i]! *= i / f;
  }
  return out;
}

function wav(buf: Buf): Buffer {
  const data = Buffer.alloc(buf.length * 2);
  for (let i = 0; i < buf.length; i++)
    data.writeInt16LE(Math.max(-32768, Math.min(32767, Math.round(buf[i]! * 32767))), i * 2);
  const head = Buffer.alloc(44);
  head.write("RIFF", 0);
  head.writeUInt32LE(36 + data.length, 4);
  head.write("WAVEfmt ", 8);
  head.writeUInt32LE(16, 16);
  head.writeUInt16LE(1, 20);
  head.writeUInt16LE(1, 22);
  head.writeUInt32LE(RATE, 24);
  head.writeUInt32LE(RATE * 2, 28);
  head.writeUInt16LE(2, 32);
  head.writeUInt16LE(16, 34);
  head.write("data", 36);
  head.writeUInt32LE(data.length, 40);
  return Buffer.concat([head, data]);
}

/* ── two more voices, for the weight ──────────────────────────────── */

/**
 * A band-limited sawtooth.
 *
 * Summed harmonics rather than a naive ramp: a ramp aliases — every partial
 * above half the sample rate folds back down as an inharmonic whine — and
 * this is the voice that carries the chord, so it is the one that must not
 * buzz. The harmonic count is capped per note, so a high voice has fewer.
 */
function sawAt(freq: number, t: number): number {
  const n = Math.max(1, Math.min(34, Math.floor(RATE / 2 / freq)));
  let v = 0;
  for (let k = 1; k <= n; k++) v += Math.sin(2 * Math.PI * k * freq * t) / k;
  return v * 0.55;
}

/**
 * The brass-ish voice: detuned saws through a lowpass that OPENS.
 *
 * A filter sweeping upward as the note starts is most of what "big" sounds
 * like — it is a brass section leaning into a note, and it is why a static
 * waveform reads as a beep however loud you make it.
 *
 * Three voices a few cents apart, because one oscillator is thin and two is
 * an audible beat. `swell` is the slow attack that makes a note arrive
 * rather than appear.
 */
function brass(
  freq: number,
  dur: number,
  { gain = 1, swell = 0.05, decay = 1.6, open = 3.4, sub = 0.3 } = {},
): Buf {
  const n = seconds(dur);
  const out = make(dur);
  const detune = [-0.004, 0, 0.0045];
  let lp1 = 0;
  let lp2 = 0;
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    let v = 0;
    for (const d of detune) v += sawAt(freq * (1 + d), t);
    v /= detune.length;
    if (sub > 0) v += Math.sin(2 * Math.PI * (freq / 2) * t) * sub;

    // Cutoff rides from an octave above the note up to `open` octaves,
    // fastest at the start.
    const k = 1 - Math.exp((-7 * i) / n);
    const cutoff = Math.min(16000, freq * 2 * Math.pow(2, open * k));
    const c = Math.min(1, (2 * Math.PI * cutoff) / RATE);
    lp1 += c * (v - lp1);
    lp2 += c * (lp1 - lp2);

    const a = Math.min(1, t / swell);
    out[i] = lp2 * a * Math.exp((-decay * i) / n) * gain;
  }
  return out;
}

/** Wide detuned voices with a slow attack. Warmth under a landing. */
function choir(freq: number, dur: number, { gain = 1, swell = 0.12, decay = 2.2 } = {}): Buf {
  const n = seconds(dur);
  const out = make(dur);
  const voices = [-0.007, -0.003, 0, 0.003, 0.007];
  for (let i = 0; i < n; i++) {
    const t = i / RATE;
    let v = 0;
    for (const d of voices) {
      const f = freq * (1 + d);
      v += Math.sin(2 * Math.PI * f * t) + 0.2 * Math.sin(4 * Math.PI * f * t);
    }
    const a = Math.min(1, t / swell);
    out[i] = (v / voices.length) * a * Math.exp((-decay * i) / n) * gain * 0.6;
  }
  return out;
}

/* ── the idents ────────────────────────────────────────────────────── */

interface Sting {
  id: string;
  /** What it is and what it is reaching for. */
  idea: string;
  build: () => Buf;
}

/*
 * ═══ WHY THE FIRST FIVE SOUNDED LIKE ERRORS ═══
 *
 * Or: *"there still aren't 5 options we could pick from. 3 is the only one
 * that comes close. It can't sound like an error sound. It needs something
 * slightly epic. Not too pretentious, but a bit big."*
 *
 * Two of them WERE error sounds, and one by construction without my noticing:
 * #2 was a descending minor third, the universal interval for "wrong" —
 * every game, lift and microwave on earth. #1 and #5 were two bare notes
 * with a gap between them, which is the shape of an alert whatever the
 * pitches are. #4 landed on a minor chord.
 *
 * #3 was the one that worked, and what it does differently is the lesson:
 *
 *   - it RISES. Upward motion reads as arrival; downward reads as failure.
 *   - it lands on a MAJOR CHORD rather than stopping on one note.
 *   - the landing SUSTAINS instead of being struck and dropped.
 *
 * So all five below rise, all five land on D major, and all five put weight
 * under that landing — a sub octave and a filter that opens, which is what
 * "big" actually is. They differ in the route up and in what is singing,
 * which is a choice worth offering. "Two notes versus three notes" was not.
 *
 * Short, though. Epic for two seconds is a studio ident; epic for six is a
 * film company, and this plays before a card game a seven-year-old opens
 * forty times a week.
 */
const CHORD = ["D3", "F#3", "A3", "D4"];

const STINGS: Sting[] = [
  /*
   * ═══ THREE AND FOUR, CROSSED ═══
   *
   * Hod picked 4, the choir. Or picked 3, and said which part: *"especially
   * the beginning of 3"* — the crescendo, before anything lands.
   *
   * Those are not a disagreement, they are the two halves of one sting. 3's
   * opening is a RUN-UP and 4's body is an ARRIVAL, and neither had the other
   * before: 3 landed on brass, which is the part Or did not single out, and 4
   * began on a voice already singing, with nothing to arrive from.
   *
   * So all three below are 3's crescendo into 4's voices. They differ in how
   * long the run-up gets and how much metal is left in the landing, which is
   * the only real question left.
   */
  {
    id: "1-rise-into-voices",
    idea: "Straight down the middle: his run-up, Hod's choir, nothing else.",
    build: () => {
      const out = make(2.7);
      const L = 0.5;
      // The part Or singled out: air, and a fifth growing under it.
      at(out, air(L + 0.05, { cutoff: 5200, gain: 0.26, rise: true }), 0);
      at(out, brass(note("D2"), L + 0.1, { gain: 0.22, swell: L * 0.9, decay: 0.2, open: 2.2 }), 0);
      at(out, brass(note("A2"), L + 0.1, { gain: 0.16, swell: L * 0.9, decay: 0.2, open: 2.2 }), 0);
      // And then voices rather than brass.
      ["D3", "A3", "D4", "F#4", "A4"].forEach((n, i) =>
        at(out, choir(note(n), 2.1, { gain: 0.36 - i * 0.04, swell: 0.05, decay: 1.5 }), L),
      );
      at(out, thud(note("D1"), 1.5, { decay: 2.9, gain: 0.78 }), L);
      at(out, bell(note("D6"), 1.5, { ratio: 2.0, index: 1.6, decay: 3.0, gain: 0.13 }), L + 0.04);
      return finish(room(out, { mix: 0.32 }));
    },
  },
  {
    id: "2-longer-run",
    idea: "The same, with twice the run-up. The most cinematic of the three.",
    build: () => {
      const out = make(3.0);
      const L = 0.8;
      at(out, air(L + 0.05, { cutoff: 5600, gain: 0.3, rise: true }), 0);
      at(out, brass(note("D2"), L + 0.1, { gain: 0.24, swell: L * 0.92, decay: 0.2, open: 2.4 }), 0);
      at(out, brass(note("A2"), L + 0.1, { gain: 0.17, swell: L * 0.92, decay: 0.2, open: 2.4 }), 0);
      // A voice joins the climb before the chord does, so the arrival is
      // something the run-up was already becoming.
      at(out, choir(note("D4"), L, { gain: 0.14, swell: L * 0.8, decay: 0.3 }), 0.2);
      ["D3", "A3", "D4", "F#4", "A4"].forEach((n, i) =>
        at(out, choir(note(n), 2.1, { gain: 0.36 - i * 0.04, swell: 0.05, decay: 1.4 }), L),
      );
      at(out, thud(note("D1"), 1.6, { decay: 2.7, gain: 0.85 }), L);
      at(out, bell(note("D6"), 1.4, { ratio: 2.0, index: 1.5, decay: 3.2, gain: 0.12 }), L + 0.05);
      return finish(room(out, { mix: 0.34 }));
    },
  },
  {
    id: "3-voices-with-weight",
    idea: "Voices in front, but brass underneath them. Warm and still big.",
    build: () => {
      const out = make(2.8);
      const L = 0.5;
      at(out, air(L + 0.05, { cutoff: 5200, gain: 0.24, rise: true }), 0);
      at(out, brass(note("D2"), L + 0.1, { gain: 0.22, swell: L * 0.9, decay: 0.2, open: 2.2 }), 0);
      at(out, brass(note("A2"), L + 0.1, { gain: 0.16, swell: L * 0.9, decay: 0.2, open: 2.2 }), 0);
      // Voices carry the chord; brass sits beneath holding it up rather than
      // singing it, which is where 4 felt thin and 3 felt cold.
      ["D3", "A3", "D4", "F#4", "A4"].forEach((n, i) =>
        at(out, choir(note(n), 2.1, { gain: 0.32 - i * 0.035, swell: 0.05, decay: 1.5 }), L),
      );
      ["D2", "A2", "D3"].forEach((n, i) =>
        at(out, brass(note(n), 2.0, { gain: 0.17 - i * 0.03, swell: 0.03, decay: 1.7, open: 2.6 }), L),
      );
      at(out, thud(note("D1"), 1.7, { decay: 2.6, gain: 0.95 }), L);
      at(out, bell(note("D5"), 1.6, { ratio: 2.0, index: 2.2, decay: 2.6, gain: 0.22 }), L + 0.02);
      return finish(room(out, { mix: 0.3 }));
    },
  },
];

/* ── run ───────────────────────────────────────────────────────────── */

function ffmpeg(): string {
  const winget = join(
    process.env.LOCALAPPDATA ?? "",
    "Microsoft/WinGet/Packages/Gyan.FFmpeg_Microsoft.Winget.Source_8wekyb3d8bbwe",
    "ffmpeg-8.1.1-full_build/bin/ffmpeg.exe",
  );
  return existsSync(winget) ? winget : "ffmpeg";
}

mkdirSync(OUT, { recursive: true });
const only = process.argv[2];
console.log();
for (const s of STINGS) {
  if (only && !s.id.startsWith(only)) continue;
  const raw = join(OUT, `${s.id}.wav`);
  const mp3 = join(OUT, `${s.id}.mp3`);
  writeFileSync(raw, wav(s.build()));
  execFileSync(ffmpeg(), [
    "-y", "-v", "error", "-i", raw,
    // -16 LUFS is where the game's own effects sit, so the ident does not
    // arrive louder than the thing it introduces.
    "-af", "loudnorm=I=-16:TP=-1.5:LRA=11",
    "-ac", "1", "-ar", "44100", "-b:a", "160k", mp3,
  ]);
  console.log(`   ${s.id.padEnd(18)} ${s.idea}`);
}
console.log(`\n   → ${OUT}\n`);
